-- LOCAL PRO ONLY. Read-only commercial progress from explicit conversion facts.
-- No stage/core/receipt backfill. Existing payloads and history remain unchanged.
begin;
create or replace function public.pro_lead_commercial_work_authorize(p_actor uuid,p_action uuid) returns void language plpgsql security invoker set search_path=public,pg_temp as $$declare r pro_manual_lead_works;begin
 perform pro_lead_origin_owner(p_actor);select * into r from pro_manual_lead_works where owner_id=p_actor and action_id=p_action;if not found then raise exception 'Conversion unavailable' using errcode='42501';end if;
 if not exists(select 1 from pro_lead_center_records where owner_id=p_actor and kind='manual' and id=r.lead_id)or not exists(select 1 from pro_work where user_id=p_actor and id=r.work_id_text and "clientId"=r.source_client_id and "bookingClientId"is null)then raise exception 'Conversion ownership unavailable' using errcode='42501';end if;end $$;
create or replace function public.pro_lead_commercial_work_action_read(p_actor uuid,p_action uuid) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$declare r pro_manual_lead_works;begin
 perform pro_lead_origin_owner(p_actor);select * into r from pro_manual_lead_works where owner_id=p_actor and action_id=p_action;if not found then return jsonb_build_object('receipt',null);end if;perform pro_lead_commercial_work_authorize(p_actor,p_action);return jsonb_build_object('receipt',jsonb_build_object('input',r.input,'result',r.result));end $$;
create or replace function public.pro_lead_commercial_work_mapping_read(p_actor uuid,p_lead uuid) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$declare r pro_manual_lead_works;begin
 perform pro_lead_origin_owner(p_actor);if not exists(select 1 from pro_lead_center_records where owner_id=p_actor and kind='manual' and id=p_lead)then raise exception 'Opportunity unavailable' using errcode='P0002';end if;
 select * into r from pro_manual_lead_works where owner_id=p_actor and lead_id=p_lead;if not found then return jsonb_build_object('mapping',null);end if;perform pro_lead_commercial_work_authorize(p_actor,r.action_id);return jsonb_build_object('mapping',r.result);end $$;
create or replace function public.pro_lead_commercial_work_context(p_actor uuid,p_lead uuid) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$declare l pro_lead_center_records;c pro_clients;m jsonb;begin
 perform pro_lead_origin_owner(p_actor);select * into l from pro_lead_center_records where owner_id=p_actor and kind='manual' and id=p_lead;if not found then raise exception 'Opportunity unavailable' using errcode='P0002';end if;
 m:=pro_lead_commercial_work_mapping_read(p_actor,p_lead)->'mapping';select * into c from pro_clients where user_id=p_actor and id=l.client_id;
 if not found then raise exception 'Private customer unavailable' using errcode='42501';end if;
 if m='null'::jsonb and(l.archived or c.archived)then raise exception 'Restore the opportunity and customer before converting' using errcode='40001';end if;
 return jsonb_build_object('source',jsonb_build_object('leadId',l.id,'leadRevision',l.revision,'clientId',l.client_id),'client',jsonb_build_object('id',c.id,'name',c.name,'archived',c.archived),'service',l.title,'mapping',m);end $$;
create or replace function public.pro_lead_commercial_work_convert(p_actor uuid,p_input jsonb) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$declare aid uuid;lid uuid;wid uuid;rev integer;l pro_lead_center_records;c pro_clients;r pro_manual_lead_works;v integer;w jsonb;answer jsonb;begin
 perform pro_lead_origin_owner(p_actor);
 if jsonb_typeof(p_input)is distinct from'object'or not(p_input?&array['action','actionId','leadId','leadRevision','workId'])or exists(select 1 from jsonb_object_keys(p_input)k where k<>all(array['action','actionId','leadId','leadRevision','workId']))or p_input->>'action'is distinct from'convert'or jsonb_typeof(p_input->'actionId')is distinct from'string'or jsonb_typeof(p_input->'leadId')is distinct from'string'or jsonb_typeof(p_input->'workId')is distinct from'string'or jsonb_typeof(p_input->'leadRevision')is distinct from'number'or not coalesce(p_input->>'leadRevision'~'^[0-9]{1,10}$',false)or(p_input->>'leadRevision')::numeric not between 1 and 2147483647 then raise exception 'Invalid conversion' using errcode='22023';end if;
 aid:=(p_input->>'actionId')::uuid;lid:=(p_input->>'leadId')::uuid;wid:=(p_input->>'workId')::uuid;rev:=(p_input->>'leadRevision')::integer;
 -- Reentrant old core/customer owner lock precedes catalogue/source rows.
 perform pg_advisory_xact_lock(hashtextextended(p_actor::text,0));perform pg_advisory_xact_lock(hashtextextended('pro-manual-lead-work-action:'||p_actor::text||':'||aid::text,0));perform pg_advisory_xact_lock(hashtextextended('pro-request-pipeline-catalog:'||p_actor::text,0));perform pro_lead_origin_owner(p_actor);
 select * into r from pro_manual_lead_works where owner_id=p_actor and action_id=aid;if found then perform pro_lead_commercial_work_authorize(p_actor,aid);if r.input is distinct from p_input then raise exception 'Conversion action reused' using errcode='22023';end if;return r.result;end if;
 select * into l from pro_lead_center_records where owner_id=p_actor and kind='manual'and id=lid for update;if not found then raise exception 'Opportunity unavailable' using errcode='42501';end if;
 if exists(select 1 from pro_manual_lead_works where owner_id=p_actor and lead_id=lid)then raise exception 'Opportunity already converted' using errcode='40001';end if;
 if l.archived or l.revision<>rev then raise exception 'Opportunity changed' using errcode='40001';end if;
 if exists(select 1 from pro_work where user_id=p_actor and id=wid::text)then raise exception 'Work identity already exists' using errcode='40001';end if;
 select * into c from pro_clients where user_id=p_actor and id=l.client_id for update;if not found or c.archived then raise exception 'Choose an active private customer' using errcode='40001';end if;perform pro_lead_origin_owner(p_actor);
 select revision into v from pro_workspace_core where user_id=p_actor for update;if coalesce(v,0)>=2147483647 then raise exception 'Workspace revision exhausted' using errcode='40001';end if;
 w:=jsonb_build_object('id',wid,'client',c.name,'service',l.title,'stage','new','start','','end','','clientId',c.id,'cancelled',false);
 perform pro_patch_core(p_actor,'work',w,coalesce(v,0));perform pro_lead_origin_owner(p_actor);
 answer:=jsonb_build_object('action','convert','link',jsonb_build_object('leadId',lid,'sourceLeadRevision',rev,'sourceClientId',c.id,'workId',wid,'createdAt',now()),'work',w);
 insert into pro_manual_lead_works(owner_id,action_id,lead_id,source_lead_revision,source_client_id,source_snapshot,work_id,input,result,actor_name)values(p_actor,aid,lid,rev,c.id,pro_lead_center_manual_json(l),wid,p_input,answer,pro_team_name(p_actor));perform pro_lead_commercial_work_authorize(p_actor,aid);return answer;end $$;
create or replace function public.pro_lead_commercial_progress(p_actor uuid,p_kind text,p_id uuid)returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare l pro_lead_center_records;r jsonb;conv jsonb;automatic_stage text;effective text;current_mode text;begin
 perform pro_lead_origin_owner(p_actor);if p_kind is null or p_kind not in('manual','request')then raise exception'Invalid lead kind'using errcode='22023';end if;
 if p_kind='request'then r:=pro_lead_origin_request(p_actor,p_id);return jsonb_build_object('kind',p_kind,'id',p_id,'mode',r->'state'->'mode','automaticStageId',r->'automaticStageId','effectiveStageId',r->'effectiveStageId','conversion',null);end if;
 select*into l from pro_lead_center_records where owner_id=p_actor and kind='manual'and id=p_id;if not found then raise exception'Opportunity unavailable'using errcode='P0002';end if;
 select jsonb_build_object('actionId',m.action_id,'workId',m.work_id,'at',m.created_at)into conv from pro_manual_lead_works m join pro_work w on w.user_id=m.owner_id and w.id=m.work_id_text and w."clientId"=m.source_client_id and w."bookingClientId"is null where m.owner_id=p_actor and m.lead_kind='manual'and m.lead_id=p_id;
 automatic_stage:=case when conv is null then'new'else'won'end;current_mode:=l.stage_mode;effective:=case when current_mode='manual'then l.stage_id else automatic_stage end;
 select coalesce(reassign_to_id,effective)into effective from pro_request_pipeline_stages where owner_id=p_actor and id=effective;effective:=coalesce(effective,case when current_mode='manual'then l.stage_id else automatic_stage end);
 return jsonb_build_object('kind',p_kind,'id',p_id,'mode',current_mode,'automaticStageId',automatic_stage,'effectiveStageId',effective,'conversion',conv);end $$;
create or replace function public.pro_lead_commercial_sources(p_actor uuid,p_archived boolean,p_query text)returns table(kind text,id uuid,created_at timestamptz,effective_stage text,fingerprint text)language plpgsql stable security invoker set search_path=public,pg_temp as $$begin
 perform pro_lead_origin_owner(p_actor);if p_archived is null or p_query is null or length(p_query)>100 then raise exception'Invalid lead sources query'using errcode='22023';end if;
 return query with base as materialized(select*from pro_lead_center_sources(p_actor,p_archived,p_query))
 select b.kind,b.id,b.created_at,case when b.kind='manual'and l.stage_mode='automatic'then case when w.id is null then'new'else'won'end else b.effective_stage end,
 md5(b.fingerprint||jsonb_build_array(m.action_id,m.work_id,m.source_client_id,m.created_at,w.id)::text)
 from base b left join pro_lead_center_records l on l.owner_id=p_actor and l.kind='manual'and l.id=b.id and b.kind='manual'
 left join pro_manual_lead_works m on m.owner_id=p_actor and m.lead_kind='manual'and m.lead_id=l.id
 left join pro_work w on w.user_id=m.owner_id and w.id=m.work_id_text and w."clientId"=m.source_client_id and w."bookingClientId"is null;end $$;
create or replace function public.pro_lead_commercial_read(p_actor uuid,p_status text default 'active',p_stage text default null,p_query text default '',p_channel text default null,p_after text default null,p_snapshot text default null) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare catalog jsonb;answer jsonb;actual_token text;cursor_valid boolean;begin
 perform pro_lead_origin_owner(p_actor);catalog:=pro_lead_origin_stage_catalog(p_actor);if p_status is null or p_status not in('active','archived') or p_query is null or length(p_query)>100 or p_stage is not null and not exists(select 1 from jsonb_array_elements(catalog->'stages')s where s->>'id'=p_stage) or p_after is not null and p_after!~'^(manual|request):[a-f0-9-]{36}$' then raise exception 'Invalid lead query' using errcode='22023';end if;
 if(p_after is null)<>(p_snapshot is null)or(p_channel is not null and p_channel<>'unspecified'and pro_lead_origin_channel_json(p_actor,p_channel)is null)then raise exception'Invalid attribution filter'using errcode='22023';end if;
 with sources as materialized(select s.*,a.channel_id,coalesce(a.revision,0)origin_revision,case when s.kind='request'then exists(select 1 from pro_clients c join pro_appointment_requests r on r.owner_id=c.user_id and c.id='reservation-'||r.client_user_id::text where r.owner_id=p_actor and r.id=s.id and c.archived)else false end private_client_archived from pro_lead_commercial_sources(p_actor,p_status='archived',p_query)s left join pro_lead_origin_assignments a on a.owner_id=p_actor and a.kind=s.kind and a.id=s.id where p_channel is null or p_channel='unspecified'and a.channel_id is null or a.channel_id=p_channel),
 metadata as(select md5(p_actor::text||p_status||coalesce(p_stage,'all')||p_query||coalesce(p_channel,'all')||catalog::text||(select coalesce(jsonb_agg(to_jsonb(c)order by id)::text,'[]')from pro_lead_origin_catalog(p_actor)c)||coalesce(string_agg(jsonb_build_array(kind,id,created_at,effective_stage,fingerprint,channel_id,origin_revision,private_client_archived)::text,',' order by created_at desc,kind,id desc),''))token from sources),
 anchor as(select * from sources where kind=split_part(p_after,':',1) and id=split_part(p_after,':',2)::uuid and(p_stage is null or effective_stage=p_stage)),
 selected as materialized(select * from sources where(p_stage is null or effective_stage=p_stage) and(p_after is null or created_at<(select created_at from anchor) or created_at=(select created_at from anchor) and(kind>(select kind from anchor) or kind=(select kind from anchor) and id<(select id from anchor))) order by created_at desc,kind,id desc limit 21),
 page as(select coalesce(jsonb_agg(pro_lead_origin_item(p_actor,kind,id) order by created_at desc,kind,id desc),'[]'::jsonb)items from(select * from selected order by created_at desc,kind,id desc limit 20)v),
 counts as(select jsonb_agg(jsonb_build_object('stageId',s->>'id','count',(select count(*) from sources where effective_stage=s->>'id')) order by(s->>'position')::integer)items from jsonb_array_elements(catalog->'stages')s)
 select jsonb_build_object('catalog',catalog,'items',page.items,'counts',counts.items,'nextCursor',case when(select count(*) from selected)>20 then(select kind||':'||id::text from selected order by created_at desc,kind,id desc offset 19 limit 1)else null end,'snapshotToken',metadata.token),metadata.token,(p_after is null or exists(select 1 from anchor)) into answer,actual_token,cursor_valid from page cross join counts cross join metadata;
 if p_after is not null and(p_snapshot is null or p_snapshot<>actual_token or not cursor_valid) then raise exception 'Leads changed; refresh before continuing' using errcode='40001';end if;return jsonb_build_object('page',answer,'stages',coalesce((select jsonb_agg(pro_lead_commercial_progress(p_actor,i->>'kind',(i->>'id')::uuid)order by n)from jsonb_array_elements(answer->'items')with ordinality x(i,n)),'[]'),'context',coalesce((select jsonb_agg(pro_lead_origin_get(p_actor,i->>'kind',(i->>'id')::uuid)order by n)from jsonb_array_elements(answer->'items')with ordinality x(i,n)),'[]'));end $$;
create or replace function public.pro_lead_commercial_metrics(p_actor uuid,p_status text default'active',p_stage text default null,p_query text default'',p_from date default null,p_to date default null,p_after text default null,p_snapshot text default null)returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare answer jsonb;catalog jsonb;begin
 perform pro_lead_origin_owner(p_actor);catalog:=pro_lead_origin_stage_catalog(p_actor);
 if p_status is null or p_status not in('active','archived')or p_query is null or length(p_query)>100 or p_stage is not null and not exists(select 1 from jsonb_array_elements(catalog->'stages')s where s->>'id'=p_stage)or(p_after is null)<>(p_snapshot is null)or p_from is not null and p_from not between date'1900-01-01'and date'2100-12-31'or p_to is not null and p_to not between date'1900-01-01'and date'2100-12-31'or p_from>p_to then raise exception'Invalid metrics query'using errcode='22023';end if;
 with sources as materialized(select s.*,a.channel_id,coalesce(a.revision,0)origin_revision,case when s.kind='request'then exists(select 1 from pro_clients c join pro_appointment_requests r on r.owner_id=c.user_id and c.id='reservation-'||r.client_user_id::text where r.owner_id=p_actor and r.id=s.id and c.archived)else false end private_client_archived from pro_lead_commercial_sources(p_actor,p_status='archived',p_query)s left join pro_lead_origin_assignments a on a.owner_id=p_actor and a.kind=s.kind and a.id=s.id where(p_stage is null or s.effective_stage=p_stage)and(p_from is null or(s.created_at at time zone'America/Costa_Rica')::date>=p_from)and(p_to is null or(s.created_at at time zone'America/Costa_Rica')::date<=p_to)),
 groups as(select channel_id,count(*)filter(where kind='manual')manual,count(*)filter(where kind='request')request,count(*)total,count(*)filter(where effective_stage='won')won from sources group by channel_id),
 rows as(select 'unspecified'::text id,'0'::text ordering,null::text channel_id,coalesce(g.manual,0)manual,coalesce(g.request,0)request,coalesce(g.total,0)total,coalesce(g.won,0)won from(select 1)dummy left join groups g on g.channel_id is null union all select channel_id,'1:'||channel_id,channel_id,manual,request,total,won from groups where channel_id is not null),
 metadata as(select md5(p_actor::text||p_status||coalesce(p_stage,'all')||p_query||coalesce(p_from::text,'')||coalesce(p_to::text,'')||catalog::text||(select coalesce(jsonb_agg(to_jsonb(c)order by id)::text,'[]')from pro_lead_origin_catalog(p_actor)c)||coalesce(jsonb_agg(jsonb_build_array(kind,id,fingerprint,effective_stage,channel_id,origin_revision,private_client_archived)order by created_at desc,kind,id desc)::text,'[]'))token from sources),
 page as(select*from rows where p_after is null or ordering>(case when p_after='unspecified'then'0'else'1:'||p_after end)order by ordering limit 21)
 select jsonb_build_object('fingerprint',(select token from metadata),'items',coalesce((select jsonb_agg(jsonb_build_object('channel',pro_lead_origin_channel_json(p_actor,channel_id),'manual',manual,'request',request,'total',total,'won',won)order by ordering)from(select*from page order by ordering limit 20)p),'[]'),'totals',(select jsonb_build_object('manual',count(*)filter(where kind='manual'),'request',count(*)filter(where kind='request'),'total',count(*),'won',count(*)filter(where effective_stage='won'))from sources),'nextCursor',case when(select count(*)from page)>20 then(select id from page order by ordering offset 19 limit 1)else null end,'validCursor',p_after is null or exists(select 1 from rows where id=p_after))into answer;
 if p_after is not null and(p_snapshot is distinct from answer->>'fingerprint'or not(answer->>'validCursor')::boolean)then raise exception'Metrics changed'using errcode='40001';end if;return answer-'validCursor';end $$;
create or replace function public.pro_lead_commercial_detail(p_actor uuid,p_kind text,p_id uuid)returns jsonb language sql stable security invoker set search_path=public,pg_temp as $$select jsonb_build_object('detail',pro_lead_private_core_detail(p_actor,p_kind,p_id),'stage',pro_lead_commercial_progress(p_actor,p_kind,p_id))$$;
-- Only new functions are granted. No old function, table, trigger or row changes.
do $$declare f record;begin for f in select p.oid::regprocedure signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname like'pro_lead_commercial_%'loop execute format('revoke all on function %s from public,anon,authenticated',f.signature);execute format('grant execute on function %s to service_role',f.signature);end loop;end $$;
commit;
notify pgrst,'reload schema';
